from typing import List

# We generate valid arbitrary byte buffers intended to be consumed by fuzz stubs
# that treat FUZZ_PARAM_STR as separators/strings and use bytes to form ByteString/String.
# Goals:
# - Provide varied lengths (including 0), contents (ASCII words, numbers, unicode-UTF8-like,
#   binary with NULs), and separator-like characters to exercise SplitBy, SplitFromEndBy,
#   Partition, builders, operators, and ConversionError pointer ranges.
# - Keep under 4096 bytes.
# - Deterministic given seed, but with variability per call.

MAX_SIZE = 4096

ASCII_WORDS = [
    b"", b"a", b"A", b"0", b" ", b"\n", b"\t", b",", b";", b"|", b"::", b"--", b"__",
    b"hello", b"world", b"foo", b"bar", b"baz", b"the quick brown fox",
]
SEPARATORS = [b",", b";", b" ", b"\t", b"\n", b"|", b"::", b":::", b"/", b"\\", b"-", b"_", b"=", b":", b". "]
NUM_PATTERNS = [
    b"0", b"1", b"-1", b"+42", b"123456", b"-99999", b"0xdeadBEEF", b"0755",
    b"3.14159", b"-2.5", b"6.022e23", b"-1.0e-10", b".5", b"5.", b"NaN", b"inf", b"-inf",
]
UTF8_SAMPLES = [
    # valid UTF-8 sequences
    "こんにちは", "Привет", "😀😃😄", "café", "mañana", "über", "παράδειγμα", "中文測試",
    # mixed ascii/utf8
    "αβγ-xyz", "ελληνικά 123", "русский-текст",
]
BINARY_CHUNKS = [
    bytes(range(0, 16)),
    bytes(range(240, 256)),
    b"\x00\x00\x00",
    b"\x00\xff\x7f\x80",
    b"\x01\x00\x02\x00\x03\x00",
]

def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))

def _make_utf8(r: random.Random) -> bytes:
    s = r.choice(UTF8_SAMPLES)
    return s.encode('utf-8')

def _make_numbery(r: random.Random) -> bytes:
    parts = []
    # optionally add whitespace to test skipws behavior
    if r.random() < 0.5:
        parts.append(r.choice([b"", b" ", b"\t", b"\n"]))
    parts.append(r.choice(NUM_PATTERNS))
    # optional trailing stuff to cause split boundaries
    if r.random() < 0.5:
        parts.append(r.choice(SEPARATORS))
        parts.append(r.choice(NUM_PATTERNS))
    return b"".join(parts)

def _interleave(r: random.Random, chunks: List[bytes], sep_pool: List[bytes]) -> bytes:
    out = bytearray()
    for i, c in enumerate(chunks):
        out.extend(c)
        if i + 1 < len(chunks):
            out.extend(r.choice(sep_pool))
    return bytes(out)

def _make_split_rich(r: random.Random) -> bytes:
    # Build a buffer with many separator types and repeated substrings/characters
    tokens = []
    count = r.randint(3, 12)
    for _ in range(count):
        kind = r.randrange(6)
        if kind == 0:
            tokens.append(r.choice(ASCII_WORDS))
        elif kind == 1:
            tokens.append(_make_numbery(r))
        elif kind == 2:
            tokens.append(_make_utf8(r))
        elif kind == 3:
            tokens.append(r.choice(BINARY_CHUNKS))
        elif kind == 4:
            # repeated char run
            ch = r.getrandbits(8)
            run = r.randint(1, 20)
            tokens.append(bytes([ch]) * run)
        else:
            # random small chunk with potential NULs
            tokens.append(_rand_bytes(r, r.randint(1, 16)))
    buf = _interleave(r, tokens, SEPARATORS + [b"", b"::", b"|", b"\n", b"\t", b" "])
    # Ensure at least one of some common chars for SplitBy(ch)
    extras = bytearray()
    for ch in [ord(','), ord(';'), ord(' '), ord('\n'), ord('|'), ord(':'), ord('-')]:
        if r.random() < 0.5:
            extras.extend(bytes([ch]) * r.randint(1, 3))
    return (buf + bytes(extras))[:MAX_SIZE]

def _make_builder_payload(r: random.Random) -> bytes:
    # Construct something that when used in builders covers numbers, c-strings, floats
    parts = []
    parts.append(_make_numbery(r))
    parts.append(b" ")
    parts.append(r.choice(ASCII_WORDS) or b"x")
    parts.append(b" ")
    # float textual
    f = r.uniform(-1e6, 1e6)
    parts.append(("%.*g" % (r.randint(3, 8), f)).encode('ascii', 'ignore'))
    return b"".join(parts)

def _make_filename_like(r: random.Random) -> bytes:
    # Though FUZZ_PARAM_FILENAME not present, useful as general text with slashes/backslashes
    comp_count = r.randint(1, 6)
    comps = []
    for _ in range(comp_count):
        base = r.choice([b"tmp", b"data", b"test", b"alpha", b"beta", b"gamma", b"split", b"sep"]) + \
               (b"_" + _rand_bytes(r, r.randint(0, 3)))
        comps.append(base)
    sep = r.choice([b"/", b"\\"])  # cross-platform separators
    return sep.join(comps)

def _mix_buffers(r: random.Random) -> bytes:
    # Assemble a final buffer by concatenating several themed segments separated by newlines
    sections = []
    makers = [
        _make_split_rich,
        _make_builder_payload,
        _make_utf8,
        lambda rr: r.choice(BINARY_CHUNKS),
        _make_numbery,
        _make_filename_like,
        lambda rr: _rand_bytes(rr, rr.randint(0, 64)),
    ]
    # choose 3-7 segments
    for _ in range(r.randint(3, 7)):
        m = r.choice(makers)
        sections.append(m(r))
    # insert deliberate separators and duplicates to encourage reverse splits
    glue_options = [b"\n", b"\n\n", b"::", b"|", b",", b";", b" "]
    buf = bytearray()
    for i, seg in enumerate(sections):
        if i:
            glue = r.choice(glue_options)
            buf.extend(glue)
            if r.random() < 0.3:
                buf.extend(glue)  # duplicate separator
        buf.extend(seg)
    # Optionally prefix/suffix spaces or separators
    if r.random() < 0.5:
        buf = bytearray(r.choice(glue_options)) + buf
    if r.random() < 0.5:
        buf.extend(r.choice(glue_options))
    return bytes(buf)[:MAX_SIZE]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose one top-level strategy biased toward split-rich content to exercise Split stubs.
    choice = r.random()
    if choice < 0.45:
        return _make_split_rich(r)
    elif choice < 0.7:
        return _mix_buffers(r)
    elif choice < 0.85:
        return _make_builder_payload(r)[:MAX_SIZE]
    else:
        # Pure binary or UTF-8 heavy
        if r.random() < 0.5:
            n = r.randint(0, 1024)
            return _rand_bytes(r, n)
        else:
            # Repeat UTF-8 samples with separators to create multiple c-strings and pointer ranges
            parts = []
            for _ in range(r.randint(2, 8)):
                parts.append(_make_utf8(r))
                parts.append(r.choice([b"\n", b" ", b"::", b"|", b",", b";", b"\t"]))
            return b"".join(parts)[:MAX_SIZE]
